-- Generated by model/lib/sql/generate.mjs. L1's load of Standard Cost IN from cells/Standard Cost IN.csv in the folder of input cells, into its empty table.
-- Two rows for one cell add up.
-- @csv cells/Standard Cost IN.csv
INSERT INTO "Standard Cost IN" SELECT coalesce(k0."SKU", fpabench_error('cells name a member SKU does not have: ' || c."SKU")), coalesce(k1."Versions", fpabench_error('cells name a member Versions does not have: ' || c."Versions")), coalesce(k2."Years", fpabench_error('cells name a member Years does not have: ' || c."Years")), sum(c.value::DOUBLE PRECISION)
FROM csv c LEFT JOIN "dim SKU" k0 ON k0.name = c."SKU" LEFT JOIN "dim Versions" k1 ON k1.name = c."Versions" LEFT JOIN "dim Years" k2 ON k2.name = c."Years"
GROUP BY 1, 2, 3;
ANALYZE "Standard Cost IN";
